def sha(value):
    return hashlib.sha256(value).hexdigest()


def digest(value):
    return sha(json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False).encode())


def sources(repo):
    return {p.name: sha(p.read_bytes()) for p in sorted(repo.glob('*.py'))}


def write_json(path, value):
    with path.open('x', encoding='utf-8') as stream:
        json.dump(value, stream, sort_keys=True, indent=2, allow_nan=False)
        stream.write('\n')


def serial(value, path=(), normalized=False):
    if is_dataclass(value):
        return serial(asdict(value), path, normalized)
    if isinstance(value, Image.Image):
        return {'image': {'mode': value.mode, 'size': list(value.size),
            'sha256': sha(value.tobytes()), 'info': serial(dict(value.info), path, normalized),
            'exif_sha256': sha(value.getexif().tobytes())}}
    if isinstance(value, np.ndarray):
        return {'array': {'dtype': str(value.dtype), 'shape': list(value.shape),
            'sha256': sha(value.tobytes())}}
    if isinstance(value, dict):
        return {str(key): serial(item, (*path, key), normalized)
                for key, item in value.items()
                if not normalized or (*path, key) not in VOLATILE_PATHS}
    if isinstance(value, (tuple, list)):
        return [serial(item, path, normalized) for item in value]
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, bytes):
        return {'bytes': len(value), 'sha256': sha(value)}
    if value is None or isinstance(value, (bool, str, int, float)):
        return value
    raise TypeError(f'Unaccounted full output at {path}: {type(value).__name__}')


def close_images(value, borrowed=(), seen=None):
    seen = set() if seen is None else seen
    if id(value) in seen or any(value is image for image in borrowed):
        return
    seen.add(id(value))
    if isinstance(value, Image.Image):
        value.close()
    elif isinstance(value, dict):
        for item in value.values(): close_images(item, borrowed, seen)
    elif isinstance(value, (tuple, list)):
        for item in value: close_images(item, borrowed, seen)


def is_open(image):
    if image is None:
        return False
    try:
        image.getpixel((0, 0))
        return True
    except (ValueError, AttributeError):
        return False


def source_image(kind, size=(73, 55), orientation=None):
    width, height = size
    y, x = np.indices((height, width))
    raw = np.empty((height, width, 4), dtype=np.uint8)
    raw[..., 0] = (x * 11 + y * 3) % 256
    raw[..., 1] = (x * 5 + y * 7) % 256
    raw[..., 2] = (x * 2 + y * 13) % 256
    raw[..., 3] = np.array([0, 1, 127, 128, 254, 255], dtype=np.uint8)[(x + y) % 6]
    if kind == 'rgba_opaque': raw[..., 3] = 255
    if kind == 'rgba_hidden': raw[..., 3] = 0
    base = Image.fromarray(raw)
    result = base
    mode = {'rgb': 'RGB', 'rgb_keyed': 'RGB', 'l_keyed': 'L',
            'la': 'LA', 'palette': 'P', 'premultiplied': 'RGBa'}.get(kind)
    if mode:
        result = base.convert(mode)
        base.close()
    if kind in ('rgb_keyed', 'l_keyed'):
        result.info['transparency'] = result.getpixel((1, 1))
    if kind == 'palette': result.info['transparency'] = bytes(range(256))
    result.info['fixture_marker'] = 'borrowed portrait source'
    exif = result.getexif()
    exif[270] = 'Portrait preparation source'
    if orientation is not None: exif[274] = orientation
    result.info['exif'] = exif.tobytes()
    return result


class Observe:
    def __init__(self, source, boundary=None):
        self.source = source
        self.boundary = boundary
        self.depth = 0
        self.before_resize = True
        self.stopped = boundary == 'initial_stop'
        self.calls = Counter()
        self.events = []
        self.refs = []
        self.prepared = []
        self.first_resize = None

    def cancelled(self):
        if self.boundary == 'subject_lift_stop' and not self.stopped:
            frame = sys._getframe(1)
            try:
                while frame is not None:
                    if (frame.f_code.co_name == '_prepare_portrait_image_impl'
                            and frame.f_locals.get('px') is not None):
                        self.stopped = True
                        break
                    frame = frame.f_back
            finally:
                frame = None
        return self.stopped

    def owned_state(self):
        result = []
        seen = set()
        for reference, mode, size in self.refs:
            image = reference()
            if image is not None and id(image) in seen:
                continue
            if image is not None: seen.add(id(image))
            result.append({'mode': mode, 'size': list(size),
                'alive_wrapper': image is not None, 'open_core': is_open(image),
                'borrowed': image is self.source})
            image = None
        return result

    @contextmanager
    def installed(self):
        real_prepare = portrait.prepare_portrait_image
        real_copy = Image.Image.copy
        real_convert = Image.Image.convert
        real_resize = Image.Image.resize
        real_orient = ImageOps.exif_transpose
        real_own = portrait._OwnedImages.own
        obs = self

        def prepare(*args, **kwargs):
            obs.calls['prepare'] += 1
            obs.depth += 1
            result = None
            try:
                result = real_prepare(*args, **kwargs)
                obs.prepared.append({'gray': serial(result[0]), 'fitted': list(result[1])})
                if obs.boundary == 'after_prepare_stop': obs.stopped = True
                return result
            finally:
                obs.depth -= 1
                args = (); kwargs = {}; result = None

        def own(owner, image):
            if obs.depth and image is not obs.source:
                obs.refs.append((weakref.ref(image), image.mode, image.size))
            return real_own(owner, image)

        def copied(image, *args, **kwargs):
            result = None
            try:
                result = real_copy(image, *args, **kwargs)
                if obs.depth and obs.before_resize:
                    obs.events.append({'operation': 'copy', 'mode': image.mode, 'size': list(image.size)})
                    obs.calls['copies_before_resize'] += 1
                    if image.mode == 'RGBA' and image.width * image.height == obs.source.width * obs.source.height:
                        obs.calls['full_source_rgba_copies_before_resize'] += 1
                        obs.calls['nominal_rgba_pixel_bytes_copied'] += image.width * image.height * 4
                return result
            finally:
                image = result = None; args = (); kwargs = {}

        def converted(image, mode=None, *args, **kwargs):
            result = None
            try:
                if obs.depth and obs.before_resize:
                    obs.events.append({'operation': 'convert', 'from': image.mode,
                        'to': mode, 'size': list(image.size)})
                    if obs.boundary == 'native_gray_error' and mode == 'L':
                        return real_convert(image, 'INVALID_PORTRAIT_MODE', *args, **kwargs)
                result = real_convert(image, mode, *args, **kwargs)
                return result
            finally:
                image = result = None; args = (); kwargs = {}

        def oriented(image, *args, **kwargs):
            result = None
            try:
                result = real_orient(image, *args, **kwargs)
                if obs.depth:
                    obs.calls['exif_transpose'] += 1
                    if obs.boundary == 'after_orientation_stop': obs.stopped = True
                return result
            finally:
                image = result = None; args = (); kwargs = {}

        def resized(image, size, *args, **kwargs):
            result = None
            try:
                if obs.depth and obs.before_resize:
                    obs.first_resize = {'input': serial(image), 'target': list(size),
                        'owned_at_boundary': obs.owned_state()}
                    obs.before_resize = False
                    if obs.boundary == 'native_resize_error':
                        return real_resize(image, (0, 1), *args, **kwargs)
                result = real_resize(image, size, *args, **kwargs)
                if obs.depth and obs.boundary == 'after_resize_stop': obs.stopped = True
                return result
            finally:
                image = result = None; args = (); kwargs = {}

        with ExitStack() as stack:
            stack.enter_context(patch.object(DrawBot, 'prepare_portrait_image', new=prepare))
            stack.enter_context(patch.object(portrait._OwnedImages, 'own', new=own))
            stack.enter_context(patch.object(Image.Image, 'copy', new=copied))
            stack.enter_context(patch.object(Image.Image, 'convert', new=converted))
            stack.enter_context(patch.object(Image.Image, 'resize', new=resized))
            stack.enter_context(patch.object(ImageOps, 'exif_transpose', new=oriented))
            yield prepare

    def report(self):
        return {'calls': dict(self.calls), 'events': self.events,
            'first_resize': self.first_resize, 'prepared': self.prepared,
            'owned_after_operation': self.owned_state()}


