def direct_case(out, name, source, quality='Balanced', preview=None):
    initial = serial(source)
    observer = Observe(source)
    acceleration = {}; preview_meta = {}
    result = None
    with observer.installed() as prepare:
        try:
            result, fitted = prepare(source, (128, 96), 8, 1.25, True, quality,
                gpu_mode='CPU', acceleration_meta=acceleration,
                preview_detail_mode=preview, preview_detail_meta=preview_meta,
                cancelled=observer.cancelled)
            assert result is not source and result.mode == 'L'
            before_mutation = serial(result)
            result.save(out / (name + '-gray.png'))
            row = {'name': name, 'source': initial, 'gray': before_mutation,
                'fitted': list(fitted), 'acceleration': serial(acceleration),
                'preview_detail': serial(preview_meta), 'work': observer.report()}
            result.putpixel((0, 0), (result.getpixel((0, 0)) + 1) % 256)
            assert serial(source) == initial
            write_json(out / (name + '.json'), row)
            return {'name': name, 'sha256': digest(row), 'gray': before_mutation,
                    'fitted': list(fitted), 'work': dict(observer.calls)}
        finally:
            if result is not None: result.close()


def public_case(out, name, source, style, quality, require_copies=False):
