    settings = options(style, quality)
    plan = None
    try:
        with observer.installed():
            plan = DrawBot.make_plan(source, (192, 144), settings, observer.cancelled)
        assert observer.calls['prepare'] == 1
        assert plan['options']['portrait_stats']['tone_strokes'] > 0
        assert plan['options']['paint_current_color']
        assert serial(source) == initial and is_open(source)
        if require_copies:
            assert observer.calls['full_source_rgba_copies_before_resize'] == 2
        row = {'name': name, 'source': initial, 'complete_plan': serial(plan),
            'normalized_plan': serial(plan, normalized=True), 'work': observer.report()}
        source.save(out / (name + '-source.png'))
        plan['image'].save(out / (name + '-image.png'))
        plan['preview'].save(out / (name + '-preview.png'))
        write_json(out / (name + '.json'), row)
        return {'name': name, 'complete_plan_sha256': digest(row['complete_plan']),
            'normalized_plan_sha256': digest(row['normalized_plan']),
            'gray': observer.prepared[0], 'work': dict(observer.calls),
            'path_count': plan['count']}
    finally:
        close_images(plan, (source,))


def retained_pixels(error):
    findings = []
    tb = error.__traceback__
    while tb is not None:
        frame = tb.tb_frame
        for name, value in tuple(frame.f_locals.items()):
            if type(value).__name__ == 'PixelAccess':
                try:
                    pixel = value[0, 0]
                    readable = True
                except Exception:
                    pixel = None; readable = False
                findings.append({'module': Path(frame.f_code.co_filename).name,
                    'function': frame.f_code.co_name, 'local': name,
                    'readable_after_failure': readable, 'pixel': pixel})
            value = None
        tb = tb.tb_next
        frame = None
    return findings


def lifetime_case(out, name, source, boundary, public=False):
    observer = Observe(source, boundary)
    initial = serial(source)
    retained = None
    result = None
    settings = options() if public else None
    try:
        with observer.installed() as prepare:
            try:
                result = (DrawBot.make_plan(source, (128, 96), settings, observer.cancelled)
                    if public else prepare(source, (128, 96), 8, subject_focus=True,
                        gpu_mode='CPU', cancelled=observer.cancelled))
            except BaseException as error:
                retained = error
        assert retained is not None, (name, 'boundary was not exercised')
        if boundary.endswith('_stop'):
            assert isinstance(retained, InterruptedError), (name, type(retained).__name__)
        else:
            assert isinstance(retained, (ValueError, OSError)), (name, type(retained).__name__)
        assert serial(source) == initial and is_open(source)
        row = {'name': name, 'public': public, 'boundary': boundary,
            'exception': type(retained).__name__, 'message': str(retained),
            'traceback': ''.join(traceback.format_exception(retained)),
            'source_unchanged_and_open': True, 'work': observer.report(),
            'retained_pixel_access': retained_pixels(retained)}
        write_json(out / (name + '.json'), row)
        return row
    finally:
        if retained is not None: traceback.clear_frames(retained.__traceback__)
        retained = None
        close_images(result, (source,))


def install_audit(repo, violations):
    def audit(event, arguments):
        targets = []
        if event == 'open':
            path, mode, flags = arguments
            if ((isinstance(mode, str) and any(c in mode for c in 'wax+')) or
                    isinstance(flags, int) and flags & (os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_TRUNC | os.O_APPEND)):
                targets = [(path, None)]
        elif event in ('os.remove', 'os.rmdir'):
            targets = [(arguments[0], arguments[1])]
        elif event in ('os.mkdir', 'os.chmod'):
            targets = [(arguments[0], arguments[2])]
        elif event == 'os.truncate': targets = [(arguments[0], None)]
        elif event in ('os.rename', 'os.link'):
            targets = [(arguments[0], arguments[2]), (arguments[1], arguments[3])]
        elif event == 'os.symlink': targets = [(arguments[1], arguments[2])]
        elif event in ('socket.connect', 'socket.bind'):
            violations.append({'event': event, 'target': repr(arguments)})
            raise AssertionError('The proof cannot use network or desktop services.')
        for target, directory_fd in targets:
            if not isinstance(target, (str, bytes, os.PathLike)): continue
            path = Path(os.fsdecode(target))
            if not path.is_absolute() and directory_fd is not None and directory_fd != -1:
                path = Path(os.readlink(f'/proc/self/fd/{directory_fd}')) / path
            if path.resolve().is_relative_to(repo):
                violations.append({'event': event, 'target': str(path)})
                raise AssertionError('Frozen repository write: ' + str(path))
    sys.addaudithook(audit)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo', required=True, type=Path)
    parser.add_argument('--expected-head', required=True)
    parser.add_argument('--expected-source-map', required=True)
    parser.add_argument('--output', required=True, type=Path)
    args = parser.parse_args()
    repo = args.repo.resolve(); out = args.output.resolve()
    assert not out.is_relative_to(repo)
    out.mkdir(parents=True, exist_ok=False)
    sys.dont_write_bytecode = True
    sys.path.insert(0, str(repo))
    before = sources(repo)
    report = {'head': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=repo, text=True).strip(),
        'source_before': before, 'source_before_digest': digest(before),
        'source_count': len(before), 'direct': [], 'public': [], 'lifetime': [], 'lazy': [],
        'timing_or_rss_claim': False, 'classification': 'R1502/DP42/IW08 completion; zero new IDs'}
    violations = []
    install_audit(repo, violations)
    try:
        assert report['head'] == args.expected_head
        assert digest(before) == args.expected_source_map
        global Image, ImageOps, np, portrait, DrawBot, ui_fixture, VOLATILE_PATHS
        import numpy as np
        from PIL import Image, ImageOps
        import RuntimePaths
        with tempfile.TemporaryDirectory(prefix='state-', dir=out) as directory, ExitStack() as stack:
            directory = Path(directory)
