                      audit_violations=violations)
        write_json(out / 'summary.json', report)
        print(json.dumps({'passed': report.get('passed'), 'direct': len(report['direct']),
            'public': len(report['public']), 'lifetime': len(report['lifetime']),
            'source_count': len(before), 'source_unchanged': before == after,
            'source_digest': digest(after), 'audit_violations': violations}), flush=True)
